/**
 * Field for display XRef headers.
 */
public class XRefHeaderFieldFactory : XRefFieldFactory {
	public static readonly string XREF_FIELD_NAME = "XRef Header";

	public XRefHeaderFieldFactory() : base(XREF_FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hlProvider the HighlightProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	public XRefHeaderFieldFactory(FieldFormatModel model, ListingHighlightProvider hlProvider,
			Options displayOptions, ToolOptions fieldOptions) : base(XREF_FIELD_NAME, model, hlProvider, displayOptions, fieldOptions)
    {
	}

	/* @Override */
	protected void initDisplayOptions(Options displayOptions) {
		colorOptionName = "XRef Color";
		styleOptionName = "XRef Style";
		base.initDisplayOptions(displayOptions);
	}

	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();
		if (!enabled || !(obj is CodeUnit)) {
			return null;
		}
		CodeUnit cu = (CodeUnit) obj;
		string headString = getXRefHeaderString(cu);
		if (headString == null || headString.length() == 0) {
			return null;
		}
		AttributedString @as = new AttributedString(headString, XrefColors.DEFAULT, getMetrics());
		FieldElement field = new TextFieldElement(@as, 0, 0);
		return ListingTextField.createSingleLineTextField(this, proxy, field, startX + varWidth,
			width, hlProvider);
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		object obj = bf.getProxy().getObject();
		if (!(obj is CodeUnit)) {
			return null;
		}

		CodeUnit cu = (CodeUnit) obj;
		int[] cpath = null;
		if (cu is Data) {
			cpath = ((Data) cu).getComponentPath();
		}

		Address addr = cu.getMinAddress();
		return new XRefHeaderFieldLocation(cu.getProgram(), addr, cpath, col);
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation loc) {
		if (!(loc is XRefHeaderFieldLocation)) {
			return null;
		}

		XRefHeaderFieldLocation xRefLoc = (XRefHeaderFieldLocation) loc;
		if (xRefLoc.getRefAddress() != null) {
			return null;
		}

		if (!hasSamePath(bf, loc)) {
			return null;
		}

		return new FieldLocation(index, fieldNum, xRefLoc.getRow(), xRefLoc.getCharOffset());
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel, ListingHighlightProvider provider,
			ToolOptions options, ToolOptions fieldOptions) {
		return new XRefHeaderFieldFactory(formatModel, provider, options, fieldOptions);
	}

	/*
	 * Creates a field with "XREF[m,n]:"
	 * <br>
	 * Where:<br>
	 *      m is the number of cross references <br>
	 *      n is the number of offcut cross references <br><br>
	 */
	private string getXRefHeaderString(CodeUnit cu) {
		if (cu == null) {
			return null;
		}

		Counter counter = new Counter();
		XReferenceUtils.getXReferences(cu, maxXRefs, counter);
		int fullCount = counter.intValue();
		int xRefCount = fullCount;

		string xRefCountText = Integer.toString(xRefCount);

		counter = new Counter();
		List<Reference> offcuts = XReferenceUtils.getOffcutXReferences(cu, maxXRefs, counter);
		int offcutCount = offcuts.size();

		fullCount = counter.intValue();
		string offcutCountText = Integer.toString(offcutCount);
		if (offcutCount > 0) {
			return "XREF[" + xRefCountText + "," + offcutCountText + "]: ";
		}

		if (xRefCount > 0) {
			return "XREF[" + xRefCountText + "]: ";
		}
		return null;
	}
}
